      },
      "steps": [
        {
          "sid": "S1",
          "kind": "ui",
          "desc": "滚动到联系酒店入口区域",
          "action": "scroll-until",
          "action_arg": "联系酒店",
          "step-type": "interaction",
          "page_ready": false,
          "asserts": [
            {
              "kind": "text",
              "match": "present",
              "expect": "联系酒店"
            }
          ]
        },
        {
          "sid": "S2",
          "kind": "ui",
          "desc": "检查联系电话入口商家号码展示保持现状",
          "action": "assert-text",
          "step-type": "assert",
          "asserts": [
