      ],
      "flow_source": "/Users/crazcdll07/.skills-manager/skills/ai-ui-autotest-engine/.run/tasks/0d2bdc40/inputs/flows/Flow05-订单详情页联系电话入口-商家号码保持现状.md"
    },
    {
      "case_id": "Flow06-协商取消页呼出_修改弹窗-双卡引导文案双态展示",
      "case_name": "Flow06-协商取消页呼出_修改弹窗-双卡引导文案双态展示",
      "landing_scheme": "imeituan://www.meituan.com/mrn?mrn_biz=hotel&mrn_entry=hotelchannel-order-detail&mrn_component=hotelchannel-order-detail&order_id=5035036077836749951&biz_type=1",
      "params": {
        "negotiation_order_id": "5035036077836749951"
      },
      "mock_ids": [
        "19538157",
        "19538201"
      ],
      "steps": [
        {
          "sid": "S1",
          "kind": "ui",
          "desc": "从订单详情页进入协商取消页（点击取消订单）",
          "action": "tap-text",
          "action_arg": "取消订单",
          "step-type": "interaction",
          "page_ready": true,
          "asserts": [
            {
              "kind": "visual",
              "expect": "进入取消流程页面，协商取消页（协商取消相关说明与提交入口）展示"
            }
          ]
        },
        {
          "sid": "S2",
          "kind": "ui",
          "desc": "L1：协商取消页点击联系酒店唤起底部浮层",
          "action": "tap-text",
          "action_arg": "联系酒店",
          "step-type": "interaction",
          "page_ready": true,
          "asserts": [
            {
              "kind": "visual",
              "expect": "底部浮层出现，含「在线联系 / 电话联系」等联系方式行"
            }
          ]
        },
        {
          "sid": "S2b",
          "kind": "ui",
          "desc": "L2：点击电话联系行唤起号码选择弹窗",
          "action": "tap-text",
          "action_arg": "电话联系",
          "step-type": "interaction",
          "page_ready": true,
          "asserts": [
            {
              "kind": "visual",
              "expect": "居中号码选择弹窗出现，列出商家号码（010-53913316 / 18519274883）与「取消」"
            }
          ]
        },
        {
          "sid": "S2c",
          "kind": "ui",
          "desc": "L3：点击商家号码唤起隐私号呼出弹窗",
          "action": "tap-text",
          "action_arg": "18519274883",
          "step-type": "interaction",
          "page_ready": true,
          "asserts": [
            {
              "kind": "visual",
              "expect": "隐私号呼出弹窗出现，顶部标题为「将使用该号码加密呼出」"
            }
          ]
        },
        {
          "sid": "S2v",
          "kind": "ui",
          "desc": "看：呼出弹窗双卡引导文案与元素",
          "action": "assert-text",
          "step-type": "assert",
          "asserts": [
            {
              "kind": "visual",
              "expect": "弹窗标题「将使用该号码加密呼出」正下方展示「双卡双待请确认，系统呼出号码和下方一致」"
            },
            {
              "kind": "visual",
              "expect": "弹窗内展示加密号码 185****7674 与「非本机号请修改 >」"
            },
            {
              "kind": "visual",
              "expect": "弹窗底部展示「取消」「立即呼叫」按钮及「为保证服务质量，您的通话可能被录音」提示"
            }
          ]
        },
        {
          "sid": "A1",
          "kind": "api",
          "desc": "queryuserinfo 接口返回校验",
          "api_assert": {
            "path": "/hotelorder/v1/queryuserinfo.json",
            "expected_fields": [
              {
                "source": "response",
                "field": "error.code",
                "expected": "200"
              },
              {
                "source": "response",
                "field": "data.maskMobile",
                "expected": "185****7674"
              }
            ]
          }
        },
        {
          "sid": "S3",
          "kind": "ui",
          "desc": "进入修改号码流程（点击非本机号请修改）",
          "action": "tap-text",
          "action_arg": "非本机号请修改",
          "step-type": "interaction",
          "page_ready": true,
          "asserts": [
            {
              "kind": "visual",
              "expect": "编辑态号码弹窗展示，标题变为「输入本机号码」"
            }
          ]
        },
        {
          "sid": "S3v",
          "kind": "ui",
          "desc": "看：编辑态弹窗双卡引导文案",
          "action": "assert-text",
          "step-type": "assert",
          "asserts": [
            {
              "kind": "visual",
              "expect": "编辑态弹窗展示「输入本机号码」标题"
            },
            {
              "kind": "visual",
              "expect": "「双卡双待请确认，系统呼出号码和下方一致」在编辑态弹窗内同位置展示"
            },
            {
              "kind": "visual",
              "expect": "编辑态弹窗展示「请输入本机号码」输入区"
            }
          ]
        },
        {
          "sid": "S4",
          "kind": "ui",
          "desc": "关闭弹窗（点击取消）",
          "action": "tap-text",
          "action_arg": "取消",
          "step-type": "interaction",
          "page_ready": false,
          "asserts": [
            {
              "kind": "visual",
              "expect": "编辑态号码弹窗关闭，页面恢复为协商取消页"
            }
          ]
        },
        {
          "sid": "S4v",
          "kind": "ui",
          "desc": "看：编辑态弹窗已消失",
          "action": "assert-text",
          "step-type": "assert",
          "asserts": [
            {
              "kind": "visual",
              "expect": "页面上不再展示「输入本机号码」与「双卡双待请确认，系统呼出号码和下方一致」"
            }
          ]
        }
      ],
      "flow_source": "/Users/crazcdll07/.skills-manager/skills/ai-ui-autotest-engine/.run/tasks/0d2bdc40/inputs/flows/Flow06-协商取消页呼出_修改弹窗-双卡引导文案双态展示.md"
    }
  ]
}
